		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 4, "<section id=\"definitions\"><h2>1. މާނަކުރުންތައް</h2><ul><li><strong>\"Kiff Agents OÜ\"</strong>، <strong>\"އަޅުގަނޑުމެން\"</strong>، <strong>\"އަޅުގަނޑުމެންނަށް\"</strong>، <strong>\"އަޅުގަނޑުމެންގެ\"</strong> — ޚިދުމަތް ފޯރުކޮށްދޭ އެސްޓޯނިޔާގެ ޕްރައިވެޓް ލިމިޓެޑް ކުންފުނި. ރަޖިސްޓްރީ ކޯޑު 17372313.</li><li><strong>\"ކަސްޓަމަރ\"</strong>، <strong>\"ތިބާ\"</strong>، <strong>\"ތިބާގެ\"</strong> — މި ޝަރުތުތަކަށް އެއްބަސްވާ ޙަޤީޤީ ނުވަތަ ޤާނޫނީ ފަރާތް.</li><li><strong>\"ޔޫޒަރ\"</strong> — ކަސްޓަމަރގެ އެކައުންޓް މެދުވެރިކޮށް ޚިދުމަތަށް ވާސިލްވުމަށް ކަސްޓަމަރ ހުއްދަ ދޭ ކޮންމެ ފަރުދެއް.</li><li><strong>\"ޚިދުމަތް\"</strong> — <code>api.kiff.dev</code>، <code>app.kiff.dev</code>، <code>kiff.dev</code>، tafs، އަދި އަޅުގަނޑުމެން އެތަނުގައި ޝާއިޢުކުރާ ޑޮކިއުމެންޓްތަކާއި ޑޭޝްބޯޑްތަކާއި API ތައް ހިމެނޭ KIFF Cloud ޕްރޮޑަކްޓް.</li><li><strong>\"tafs\"</strong> — iPhone، iPad، Android އާއި ކޮމްޕިޔުޓަރުތަކަށް (Mac، Windows އާއި Linux) tafs އެޕް އަދި އޭގެ ފަހަތުގައިވާ ޚިދުމަތް، Setup އާއި planque (§3A) ހިމެނިގެން، އެތަނުގައި ކަސްޓަމަރެއް KIFF Card ތަކުގެ ތެރޭގައި ޢަމަލުކުރާ AI އޭޖެންޓެއްގެ އަތަށް ކަމެއް ހަވާލުކުރެއެވެ. <strong>\"taf\"</strong> އަކީ އެފަދަ އޭޖެންޓެކެވެ.</li><li><strong>\"Tenant\"</strong> — ޚިދުމަތުގެ ތެރޭގައި ކަސްޓަމަރެއްގެ ނަމުގައި ވަކިކޮށް އޮތް ވަޑީ ސަރަހައްދެއް.</li><li><strong>\"އޮޑިޓް ޑޭޓާ\"</strong> — ރަންޓައިމް މެދުވެރިކޮށް ކަސްޓަމަރުގެ ނަމުގައި ޚިދުމަތުން ބަހައްޓާ އިވެންޓްތަކާއި ނިންމުންތަކާއި ޢަމަލުތަކާއި ރުހުންތަކާއި ރަސީދުތައް.</li><li><strong>\"tafs ޑޭޓާ\"</strong> — ކަސްޓަމަރުގެ ނަމުގައި tafs އިން ބަހައްޓާ ކަންތައްތައް: ކޮންމެ taf އެއްގެ ރަނާތަކާއި ބަހުސްތައް (ކަސްޓަމަރުގެ ގުޅިފައިވާ ޓޫލްތަކުން އެއަށް އެނބުރި ދޭ ކަންތައްތައް ހިމެނިގެން)، އޭގެ ރިޕޯޓްތަކާއި މެމޯރީ ނޯޓުތަކާއި އޭގެ އެލާޓްތަކަށް ރަޖިސްޓަރ ކުރެވިފައިވާ ފޯނުތައް.</li><li><strong>\"ރަސީދު\"</strong> — ކޮންޓްރޯލް ކުރެވޭ ކޮންމެ ޢަމަލަކަށްޓަކައި ޚިދުމަތުން ދޭ ސޮއިކޮށްފައިވާ، ވާރޝަން ކުރެވިފައިވާ ނިންމުމުގެ ރެކޯޑެއް.</li><li><strong>\"ޑޮކިއުމެންޓޭޝަން\"</strong> — މި ޝަރުތުތަކުން ގުޅިފައިވާ ތާރީޚް ޖަހާފައިވާ ރިވިޜަންގައި ހުންނަ ޚިދުމަތުގެ ޓެކްނިކަލް ޑޮކިއުމެންޓްތަކާއި ރައްކާތެރިކަމުގެ ފިޔަވަޅުތައް (<a href=\"https://kiff.dev/docs/archive/2026-10-10\">kiff.dev/docs/archive/2026-10-10</a>). އޭގެ ތެރޭގައި ސްޓްރެޓީޖިކް ވައިޓްޕޭޕަރ، މާކެޓިންގ މަޢުލޫމާތުތަކާއި ވަކިން ލައިސަންސް ކުރެވިފައިވާ އޯޕަން-ސޯސް ފްރޭމްވޯކްގެ ޑޮކިއުމެންޓްތައް ނުހިމެނެއެވެ.</li><li><strong>\"DPA\"</strong> — <a href=\"/legal/dpa\">/legal/dpa</a> (އިނގިރޭސިން) ގައިވާ ޑޭޓާ ޕްރޮސެސިންގ އެއްބަސްވުން، އަޅުގަނޑުމެންގެ ޕްރޮސެސަރު ފަރާތުގެ ގުޅުން ކޮންޓްރޯލް ކުރާ.</li></ul></section>")
