		ctx = templ.ClearChildren(ctx)
		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 7, "<section id=\"tafs\"><h2>3A. tafs</h2><p>tafs ގައި ތިބާ ކަމެއް (މިސާލަކަށް ރިފަންޑްތައް، ބިލް ދެއްކުން ނުވަތަ ކާޑު ޑިސްޕިއުޓްތައް) taf އެއްގެ އަތަށް ހަވާލުކުރެއެވެ: ތިބާ ގުޅުއްވާ ޓޫލްތަކާއެކު، ތިބާ އެއަށް ދޭ KIFF Card ތަކުގެ ތެރޭގައި ޝެޑިއުލްއަކަށް ބަލާގެން ޢަމަލުކުރާ AI އޭޖެންޓެކެވެ. ކޮންމެ taf އެއްވެސް ހިނގަނީ އަޅުގަނޑުމެންގެ އޭޖެންޓް ރަންޓައިމްގައެވެ، އަދި އެ ބޭނުންކުރާ AI މޮޑެލް Anthropic އިން ފޯރުކޮށްދެއެވެ. ތިބާ އޭގެ ހިފެހެއްޓިފައިވާ ކޯލްތަކަށް ޖަވާބުދެނީ tafs އެޕްގައެވެ.</p><p><strong>ތިބާގެ ޓޫލްތައް ގުޅުއްވުން.</strong> taf އެއް ފަދައިން ހިނގާ tafs ގެ AI އޭޖެންޓް Setup، ޓޫލެއް ގުޅުއްވައި ކަމަކަށްޓަކައި taf އެއް ސެޓްކުރުމަށް ތިބާއަށް އެހީތެރިވެއެވެ. އެ އަމިއްލައަށް އެއްވެސް ކަމެއް ނުގުޅުއްވައެވެ. ތިބާ ޓޫލުގެ އަމިއްލަ ފޯރުކޮށްދޭ ފަރާތުގައި (މިސާލަކަށް Stripe) ވަދެ، ކޮންމެ ގުޅުމެއް، taf އަކަށް ބޭނުންކުރެވޭނެ ޓޫލްތަކާއި އޭގެ Card ތަކަށް ތިބާގެ ޑިވައިސްގައި ރުހުން ދެއެވެ. އެ ލޮގިނުގެ token ބަހައްޓަނީ އަޅުގަނޑުމެންގެ ގުޅުމުގެ ޚިދުމަތް planque އިންނެވެ. އެ އެންކްރިޕްޓް ކޮށްފައިވެއެވެ، KIFF އިން ކުރިން ނިންމާފައިވާ ކޯލެއް ކުރުމަށް ހަމައެކަނި ބޭނުންކުރެވެއެވެ، އަދި ދުވަހަކުވެސް taf އަކަށް ނުދެވެއެވެ. ޓޫލެއް ކަނޑައެޅުމުން ފޯރުކޮށްދޭ ފަރާތުގައި token ބާތިލްކޮށް އެ ފޮހެލެއެވެ.</p><p><strong>ތިބާގެ Card ތަކަކީ ތިބާގެ އިރުޝާދުތަކެވެ.</strong> taf އެއް ތިބާގެ ޓޫލްތަކަށް ވާސިލްވަނީ KIFF މެދުވެރިކޮށް ހަމައެކަނި ކަމުގައި ވާއިރު، އެ ކޮންމެ ކޯލެއް ފޮނުވުމުގެ ކުރިން taf ގެ Card ތަކާ ޗެކް ކުރެއެވެ. ތިބާ ދިން Card އެއްގެ ތެރޭގައި ހުރި ކޯލެއް ކުރެވެނީ ތިބާގެ އިރުޝާދުގެ މަތިންނެވެ. Card އަކުން ބޭރުގައި ހުރި ކޯލެއް، Card ބުނާ ގޮތަށް ހިފެހެއްޓުމަށް ނުވަތަ ބާތިލް ކުރުމަށް ލިބެއެވެ. ހިފެހެއްޓިފައިވާ ކޯލެއް ކުރެވެނީ ހިފެހެއްޓިފައިވާ ކޯލްތަކަށް ޖަވާބުދެވޭނެ ގޮތަށް ތިބާގެ އެކައުންޓުން ހުއްދަ ދޭ މީހަކު އެ ރުހުން ދިނުމަށް ފަހުއެވެ. tafs އެޕްގައި، ޖަވާބުގައި KIFF އިން ޗެކްކުރާ އެމީހުންގެ ޑިވައިސްގެ ސޮއެއް ހުރެއެވެ، އަދި ރަސީދުން އެ ހެކި ބަހައްޓައެވެ. ތިބާގެ އެކައުންޓުން KIFF އަމިއްލައަށްވެސް (ޑޭޝްބޯޑް، އޭގެ ކޮމާންޑް-ލައިން ޓޫލް، ނުވަތަ ތިބާ އެތަނުގައި ބާރުދޭ ރުހުންދޭ ފަރާތެއް) ޖަވާބުދެވިދާނެއެވެ؛ ރަސީދުން ދެން ރެކޯޑު ކުރަނީ ކާކު ޖަވާބު ދެއްވިތޯއާއި ކިހިނެއްތޯއެވެ.</p><p><strong>ތިބާގެ އަތުގައި ހުންނަ ކަންތައްތައް.</strong> ތިބާ ކޮންމެ taf އެއްގެ ކަމާއި Card ތައް ހޮވައި، އޭގެ ހިފެހެއްޓިފައިވާ ކޯލްތަކަށް ޖަވާބުދީ، ތިބާ ގުޅުއްވާ ޓޫލްތަކާއި އެކައުންޓްތައް ބޭނުންކުރުމުގެ ހައްގު ތިބާގެ އަތުގައި ވާކަން ކަށަވަރުކުރައްވައެވެ. taf އެއްގެ ރިޕޯޓްތަކާއި މެސެޖުތަކާއި މެމޯރީ ނޯޓުތައް ލިޔަނީ AI މޮޑެލެކެވެ، އަދި އެ ރަނގަޅު ނުވެދާނެއެވެ؛ އެ މައްޗަށް ބަރޯސާވުމުގެ ކުރިން މުހިންމު ކަންތައްތައް ޗެކް ކުރައްވާށެވެ.</p><p><strong>taf އެއް ހުއްޓުވުން.</strong> ތިބާއަށް taf އެއް ނުވަތަ ހުރިހާ taf ތަކެއް ހުއްޓުވައިލެވޭނެއެވެ، taf އެއް ވަގުތީގޮތުން ހުއްޓުވައިލެވޭނެއެވެ، އޭގެ ކޮންމެ Card އެއް ބާތިލް ކުރެވޭނެއެވެ، ނުވަތަ އެ ދުރުކޮށްލެވޭނެއެވެ. ތިބާ taf އެއް ހުއްޓުވާ ނުވަތަ Card އެއް ބާތިލް ކުރާ ވަގުތުން ފެށިގެން، އޭގެ ދަށުން އައު ކޯލެއް KIFF އިން ހުއްދަ ނުދެއެވެ. tafs އެޕުން taf އެއް ހުއްޓިފައިވާކަމަށް ދައްކަނީ KIFF އާއި planque ދެބޭފުޅުންވެސް ހުއްޓުން ކަށަވަރުކުރުމަށް ފަހު ހަމައެކަނި؛ އެހިނދުން ފެށިގެން planque އިން އޭގެ އެއްވެސް ކޯލެއް ނުފޮނުވައެވެ، KIFF އިން ކުރިން ވަރަށް ކުޑަ ވަގުތެއްގައި ހުއްދަ ދިން ކޯލެއް ހިމެނިގެން. ޓޫލެއްގެ ފޯރުކޮށްދޭ ފަރާތަށް ކުރިން ފޮނުވާފައިވާ ރިކުއެސްޓެއް ފުރިހަމަވެދާނެއެވެ: އަޅުގަނޑުމެން އައު ކޯލްތައް ހުއްޓުވާލަމެވެ، އެކަމަކު ފޯރުކޮށްދޭ ފަރާތް ކޮށްފައިވާ ކަމެއް ފަހަތަށް ނުވެއެވެ. planque ނެތި، KIFF ގެ ހުއްދަތައް އަމިއްލައަށް ޗެކްކުރާ ޓޫލަކުން، KIFF އިން ކުރިން ވަރަށް ކުޑަ ވަގުތެއްގައި ނެރުނު ހުއްދައެއް ހަމަ ޤަބޫލުކުރެވިދާނެއެވެ، އެންމެ ގިނައިން 90 ސިކުންތު. ހުއްޓިފައިވާ taf އެއް އަލުން ފެށުމަށް ތިބާގެ ޑިވައިސްގައި ތިބާގެ ރުހުން ބޭނުންވެއެވެ، އަދި ހުއްޓުމުގެ ކުރިން ހިފެހެއްޓިފައި ނުވަތަ ކިއުގައި ހުރި އެއްވެސް ކަމެއް އޭގެ ފަހުން ނުހިނގައެވެ.</p><p><strong>taf އެއް ދުރުކޮށްލުން</strong> އޭގެ ޝެޑިއުލް ހުއްޓުވައި އޭގެ ރަނާތަކާއި ބަހުސްތަކާއި މެމޯރީއާއި އެ ބޭނުންކުރި ކީ ފޮހެލެއެވެ. އެއަށް ކުރިންވެސް، ތިބާގެ ޓޫލްތަކުން taf އަކަށް އެނބުރި ދޭ ކަންތައްތައް ބަހައްޓަނީ އޭގެ ރަނާ ނިމެންދެން ހަމައެކަނި (ބަހުސެއްގައި އެ ކިޔާލި ކަންތައްތައް ހަމައެކަނި، އެންކްރިޕްޓް ކޮށް، އޭގެ ދެން އޮތް މެސެޖުތަކަށްޓަކައި: އެންމެ ގިނައިން ހަތަރު ގަޑިއިރާ ހަމައަށް ބޭނުންކޮށް، ދެން ފޮހެލެވެއެވެ)، އަދި އޭގެ ރަނާތަކާއި ބަހުސްތައް 30 ދުވަސް. KIFF އިން އެ ކުރި ކަންތައްތަކުގެ ރަސީދުތައް ބަހައްޓައެވެ.</p><p><strong>EU AI ޤާނޫނު.</strong> tafs އަށްޓަކައި، Kiff Agents OÜ އަކީ AI ސިސްޓަމްގެ ފޯރުކޮށްދޭ ފަރާތް ކަމަށާއި ތިބާ އޭގެ ބޭނުންކުރާ ފަރާތް ކަމަށް ވެއެވެ. ތިބާގެ ކުންފުންޏުން ބޭރުގެ މީހަކަށް taf އަކުން ލިޔާ ކޮންމެ ކަމެއްގައި އެ ލިޔީ AI އޭޖެންޓެއް ކަމަށް ބުނެވޭކަން އަޅުގަނޑުމެން ކަށަވަރުކުރަމެވެ. ތިބާ tafs ބޭނުންކުރަނީ އެ ހުށަހަޅާ ކަންތައްތަކަށް ހަމައެކަނި، AI ޤާނޫނުން މަނާކުރާ ނުވަތަ ބޮޑު ހިތްގައިރާ ގެ ގޮތުގައި ބެލޭ ކޮންމެ ބޭނުންކުރުމަކަށް ނޫނެވެ، މިސާލަކަށް މީހެއްގެ ވަޒީފާއާއި ދަރަނި ނުވަތަ އެކަށީގެންވާ ޚިދުމަތްތަކަށް ވާސިލްވުމާ ބެހޭ ނިންމުންތައް. ތިބާގެ Card ތަކުން ބޭނުންވާ އިންސާނީ ރުހުންތައް ތިބާ ދެމެހެއްޓައި، ތިބާއަށްޓަކައި tafs ބޭނުންކުރާ މީހުންނަށް އެ ކުރާ ކަމާއި އޭގެ ހައްދުތައް ވިސްނޭކަން ކަށަވަރުކުރައްވައެވެ.</p><p><strong>ޚަރަދުތައް.</strong> tafs އަކީ ތިބާގެ KIFF ޕްލޭނުގެ ބައެކެވެ (§8): taf އެއްގެ ކޮންމެ ރަނާއެއް އެ ބޭނުންކުރި AI އަށް ކްރެޑިޓް ބޭނުންކުރެއެވެ. Coach އާއި tafs ސެޓްކުރުމަކީ Coach ގެ އިންސާފުވެރި ބޭނުންކުރުމުގެ ތެރޭގައި ހިމެނެއެވެ.</p></section>")
