		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 8, "<section id=\"account\"><h2>4. އެކައުންޓްތަކާއި ވާސިލްވުން</h2><p>ޚިދުމަތް ބޭނުންކުރުމަށް ތިބާ އެކައުންޓެއް ހަދަންޖެހެއެވެ. ތިބާ ރަނގަޅު ރަޖިސްޓްރޭޝަން މައުލޫމާތު ދިނުމަށާއި، ތިބާގެ ލޮގިން މައުލޫމާތު ސިއްރުކޮށް ބެހެއްޓުމަށާއި، ތިބާގެ އެކައުންޓް ދަށުން ހިނގާ ހުރިހާ ކަމެއްގެ ޒިންމާ އުފުލުމަށް އެއްބަސްވެއެވެ.</p><p>ތިބާގެ ޢުމުރު މަދުވެގެން 16 އަހަރު، ނުވަތަ ތިބާގެ ސަރަހައްދުގެ ޑިޖިޓަލް ރުހުމުގެ ޢުމުރު، އެ ދެކަމުގެ ތެރެއިން ބޮޑު ކަމެއް، ވާންޖެހެއެވެ. ޚިދުމަތް ކުޑަކުދިންނަށް ބަހައްޓާފައެއް ނޫނެވެ.</p><p>ޚިދުމަތް ފޯރުކޮށްދެނީ <a href=\"https://www.anthropic.com/supported-countries\">Anthropic ލިސްޓްކޮށްފައިވާ</a> ގޮތަށް އޭގެ AI މޮޑެލް ފޯރުކޮށްދޭ Anthropic އިން އޭގެ އަމިއްލަ ޚިދުމަތް ފޯރުކޮށްދޭ ޤައުމުތަކާއި ސަރަހައްދުތަކުގައި ހަމައެކަނި ކަމުގައެވެ. ތިބާއަށް އެ އެހެން ތަނަކުން ބޭނުންކުރެވޭކަށް ނުވެއެވެ. ކުންފުންޏެއްގެ މައި އޮފީސް އެ ލިސްޓުން ބޭރުގައި ހުރިނަމަ، ނުވަތަ އެފަދަ މައި އޮފީހެއް ހުރި ކުންފުންޏެއް ބޮޑަށް ބޭނުންކުރާ ނުވަތަ ކޮންޓްރޯލް ކުރާ ނަމަ، އޭގެ ޔޫޒަރުން ތިބީ ކޮންތަނެއްގައިތޯ ނުބެލެވި އެ ކުންފުންޏަށް އެ ބޭނުންކުރެވޭކަށް ނުވެއެވެ. ތިބާ، ނުވަތަ ތިބާ ބޭނުންކުރާ ކުންފުނި، ޔޫރަޕިއަން ޔޫނިއަން، ޔުނައިޓެޑް ނޭޝަންސް ނުވަތަ އެމެރިކާގެ ޖަޒާތަކަށް ހުށަހެޅިފައިވާނަމަވެސް ތިބާއަށް އެ ބޭނުންކުރެވޭކަށް ނުވެއެވެ. މި ޤަވާޢިދު ގޮސްފައިވާ އެކައުންޓްތައް އަޅުގަނޑުމެން ބާތިލް ކުރާއިރު ވަގުތީގޮތުން ހުއްޓުވިދާނެއެވެ.</p><p>ތިބާގެ އެކައުންޓުގައި ތިބާ ހުއްދަދޭ ކޮންމެ ޔޫޒަރެއްގެ ޢަމަލުތަކުގެ ޒިންމާ ތިބާގެއެވެ. މި ޝަރުތުތަކުގެ ޤަބޫލުކުރެވޭ ބިދިނުމެއް ފެނިއްޖެނަމަ އަޅުގަނޑުމެންނަށް އެކަށީގެންވާ ނޯޓިސްއަކުން އެކައުންޓެއް ވަގުތީގޮތުން ހުއްޓުވިދާނެ ނުވަތަ ވާސިލްވުން ބާތިލް ކުރެވިދާނެއެވެ. ޤަބޫލުކުރެވޭ ބޭނުންކުރުމުގެ ބިދިނުންތަކަށް (ބަލާށެވެ §5) ވަގުތީގޮތުން ހުއްޓުވުން ވަގުތުން ކުރެވިދާނެއެވެ.</p></section>")
