		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 11, "<section id=\"confidentiality\"><h2>7. ސިއްރުކަން</h2><p>ކޮންމެ ފަރާތަކަށްވެސް އަނެއް ފަރާތުން ޢާންމު ނޫން މައުލޫމާތު (\"ސިއްރު މައުލޫމާތު\") ލިބިދާނެއެވެ. ލިބޭ ފަރާތުން ސިއްރު މައުލޫމާތު ބޭނުންކުރަނީ މި ޝަރުތުތަކުގެ ދަށުން އޭގެ ވާޖިބުތައް އަދާކުރުމަށާއި ހައްގުތައް ބޭނުންކުރުމަށް ބޭނުންވާ މިންވަރަކަށް ހަމައެކަނި، އަދި އޭގެ އަމިއްލަ ސިއްރު މައުލޫމާތަށް ބޭނުންކުރާ ދަރަޖައަށް މަދުވެގެން އެއް ފަދަ އިހުތިރާމްކޮށް އެ ރައްކާކުރެއެވެ.</p><p>ސިއްރު މައުލޫމާތުގައި (އ) ބިދިނުމެއް ނެތި ޢާންމުވެފައިވާ ނުވަތަ ވާ، (ށ) ހާމަކުރުމުގެ ކުރިން ލިބޭ ފަރާތް އެނގިފައި ހުރި، (ނ) ސިއްރު މައުލޫމާތު ބޭނުން ނުކުރެ ވަކިން ތަރައްޤީކުރެވުނު، ނުވަތަ (ރ) ޤާނޫނުން ހާމަކުރަންޖެހޭ (ހުއްދަ ހުރި ތަނެއްގައި އަނެއް ފަރާތަށް އެނގިވެގެން) މައުލޫމާތު ނުހިމެނެއެވެ.</p></section>")
