		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 17, "<section id=\"indemnification\"><h2>13. ބަދަލު ދިނުން</h2><p>ޚިދުމަތް، އަޅުގަނޑުމެންގެ ފަރާތުން ފޯރުކޮށްދޭ ގޮތަށާއި ތިބާ މި ޝަރުތުތަކާ އެއްގޮތަށް ބޭނުންކުރާ ގޮތަށް، އެ ތިންވަނަ ފަރާތުގެ ސިކުނޑީގެ މުދަލުގެ ހައްގުތައް ބިދިނަކަމަށް ތިންވަނަ ފަރާތުގެ ދަޢުވާތަކުން އަޅުގަނޑުމެން ތިބާ ރައްކާކުރާނަމެވެ، އަދި އެފަދަ ދަޢުވާތަކަށް ތިބާއާ ދެކޮޅަށް ފައިނަލް ގޮތުން ކަނޑައެޅިފައިވާ ގެއްލުންތައް (ނުވަތަ އެއްބަސްވެފައިވާ ހައްލު ޢަދަދު) އަޅުގަނޑުމެން ދައްކާނަމެވެ.</p><p>(އ) ތިބާގެ ކަސްޓަމަރ ޑޭޓާ ނުވަތަ ކޮންޓެންޓް؛ (ށ) މި ޝަރުތުތައް (AUP ހިމެނިގެން) ބިދިނުމުގެ ގޮތުގައި ތިބާ ޚިދުމަތް ބޭނުންކުރުން؛ ނުވަތަ (ނ) ތިބާގެ ބޮޑު ނުރައްކާތެރިކަން ނުވަތަ ޤަސްދުގައި ކުރާ ނުބައި ޢަމަލުން ކުރިމަތިވާ ތިންވަނަ ފަރާތުގެ ދަޢުވާތަކުން ތިބާ އަޅުގަނޑުމެން ރައްކާކުރާނެއެވެ، އަދި އެފަދަ ދަޢުވާތަކަށް އަޅުގަނޑުމެންނާ ދެކޮޅަށް ފައިނަލް ގޮތުން ކަނޑައެޅިފައިވާ ގެއްލުންތައް (ނުވަތަ އެއްބަސްވެފައިވާ ހައްލު ޢަދަދު) ތިބާ ދައްކާނެއެވެ.</p><p>ބަދަލު ދިނުން ދަޢުވާއާ ބެހޭ ވަގުތުން ނޯޓިސް ދިނުމާއި، ބަދަލު ދޭ ފަރާތުގެ ދިފާއާއި ހައްލުގެ އެކަނި ކޮންޓްރޯލާއި، ބަދަލު ލިބޭ ފަރާތުގެ ޤަބޫލުކުރެވޭ އެއްބާރުލުމުގެ މައްޗަށް ބަރޯސާވެއެވެ. ބަދަލު ދޭ ފަރާތަށް ބަދަލު ލިބޭ ފަރާތް މައްޗަށް ވާޖިބުތައް ދަށްކުރާ ދަޢުވާއެއް ރުހުމެއް ނެތި ހައްލުކުރެވޭކަށް ނުވެއެވެ.</p></section>")
