		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 23, "<section id=\"general\"><h2>19. ޢާންމު</h2><p><strong>ފުރިހަމަ އެއްބަސްވުން.</strong> މި ޝަރުތުތައް، ޕްރައިވަސީ ސިޔާސަތާއި، DPA އާއި، ކޮންމެ އޯޑަރ ފޯމަކާއި، ސާފުކޮށް ހިމެނިފައިވާ ކޮންމެ އިތުރު ޝަރުތަކާއެކު، އެ ވިޔަފާރީގެ ވާހަކަ ދައްކާ އަޅުގަނޑުމެންނާ ތިބާ ދެމެދުގައި ހުރި ފުރިހަމަ އެއްބަސްވުމެވެ، އަދި ކުރިން ނުވަތަ އެއްފަހަރާ ހުރި ކޮންމެ ވިސްނުމެއް ބަދަލުކުރެއެވެ.</p><p><strong>ވަކިކުރެވޭ ކަން.</strong> ޝަރުތެއް ހިންގޭކަށް ނެތް ކަމަށް ބެލިއްޖެނަމަ، ބާކީ ހުރި ބައި ހިނގާނެއެވެ.</p><p><strong>ޙަވާލުކުރުން.</strong> އަޅުގަނޑުމެންގެ ލިޔުމުން ދޭ ރުހުމެއް ނެތި ތިބާއަށް މި ޝަރުތުތައް ޙަވާލުކުރެވޭކަށް ނުވެއެވެ. އަޅުގަނޑުމެންނަށް ހިއްސާކުރުމެއް، ނަގަމުން ގެންދިއުމެއް، ނުވަތަ އަޅުގަނޑުމެންގެ ހުރިހާ މުދަލެއް ނުވަތަ ގާތްގަނޑަކަށް ހުރިހާ މުދަލެއް ވިއްކުމެއް ގުޅިގެން، ތިބާއަށް ނޯޓިސް ދީ، ރުހުމެއް ނެތި ޙަވާލުކުރެވިދާނެއެވެ.</p><p><strong>ދޫކޮށްލުމެއް ނޫން.</strong> ޝަރުތެއް ހިންގުމުގައި ފެއިލްވުމަކީ ފަހުން އެ ހިންގުމުގެ ހައްގު ދޫކޮށްލުމެއް ނޫނެވެ.</p><p><strong>ނޯޓިސްތައް.</strong> Kiff Agents OÜ އަށް ނޯޓިސްތައް ދެނީ <a href=\"mailto:legal@kiff.dev\">legal@kiff.dev</a> އަށް ނުވަތަ، ޕޯސްޓުން، Tööstuse tn 75-71, Põhja-Tallinna linnaosa, Tallinn 10416, އެސްޓޯނިޔާއަށެވެ. ތިބާއަށް ނޯޓިސްތައް ދެނީ ތިބާގެ އެކައުންޓާ ގުޅިފައިވާ އީމެއިލަށް ނުވަތަ، ތިބާ ދީފައިވާނަމަ، ތިބާ ކަނޑައެޅި ޤާނޫނީ-ނޯޓިސް އެޑްރެސަށެވެ.</p><p><strong>ޚާއްޞަ ކޮންޓްރެކްޓަރުން.</strong> މި ޝަރުތުތަކުގެ ތެރެއިން އެއްވެސް ކަމަކުން ޝަރީކުވެރިކަމެއް، އޭޖެންސީއެއް، ޖޮއިންޓް ވެންޗަރެއް ނުވަތަ ވަޒީފާގެ ގުޅުމެއް ނުއުފައްދައެވެ.</p><p><strong>ތިންވަނަ ފަރާތުގެ ފައިދާ ލިބޭ ފަރާތްތައް.</strong> ނެތެވެ، ބަދަލު ލިބޭ އެފިލިއޭޓުތައް ސާފުކޮށް ދެނެގަނެވިފައިވާ މިންވަރަކަށް ފިޔަވައެވެ.</p></section>")
